import { loadCrapsProducer } from './replay-producer.js';

export async function materializeReplay(input) {
  const { replayField, buildCrapsReplayBundle } = await loadCrapsProducer(input.ruleset?.engineVersion);
  const { tape, entries } = replayField({ ...input.terms, boundSlot: input.settlement.boundSlot, word: input.word, entrants: input.seats.length,
    ...(input.rollBudget != null ? { rollBudget: BigInt(input.rollBudget) } : {}) }, input.seats);
  return buildCrapsReplayBundle({ ...input, tape: { ...tape, maxHands: tape.offsets.length / 4 }, seats: entries.map((entry, i) => ({ entry, lane: input.seats[i].lane, chainWon: input.seats[i].chainWon, chainPaid: input.seats[i].chainPaid })) });
}
if (typeof self !== 'undefined' && typeof document === 'undefined') self.onmessage = async ({ data }) => {
  try {
    const bundle = await materializeReplay(data);
    self.postMessage({ digest: bundle.digest, pointerPath: bundle.pointerPath, entrants: bundle.entrants,
      files: [...bundle.children, bundle.manifest].map(child => ({ path: child.path, body: child.body.toString('utf8') })) });
  } catch (error) { self.postMessage({ error: error.message }); }
};
